// Server-owned data only. No credentials or administrative records in the asset bundle.
const STATES=new Set(['missing','athlete-reported','officially-verified','historical-reconfirm']);
const TOPICS=new Set(['coaching','team','sponsorship','media','general']);
const headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers});
const text=(value,max=2000)=>typeof value==='string'?value.trim().slice(0,max):'';
const safeURL=value=>!value||/^https:\/\/[^\s]+$/i.test(value);
async function body(request){if(+(request.headers.get('content-length')||0)>16000)throw Error('size');const raw=await request.text();if(raw.length>16000)throw Error('size');const parsed=JSON.parse(raw);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error('shape');return parsed}
async function list(bucket,prefix){let cursor,keys=[];do{const page=await bucket.list({prefix,cursor,limit:1000});keys.push(...page.objects);cursor=page.truncated?page.cursor:undefined}while(cursor&&keys.length<5000);return keys}
async function adminData(bucket){const keys=await list(bucket,'enquiries/');const records=await list(bucket,'records/');const now=Date.now(),enquiries=[];for(const key of keys){const value=await bucket.get(key.key);if(!value)continue;const q=await value.json();if(now-q.createdAt>90*86400000){await bucket.delete(key.key);continue}enquiries.push(q)}const credentials=await bucket.get('private/credentials.json');return {credentials:credentials?await credentials.json():{verification:'missing'},enquiries:enquiries.sort((a,b)=>b.createdAt-a.createdAt),records:await Promise.all(records.map(async k=>(await bucket.get(k.key))?.json()))}}
function allowedAdmin(request,env){const id=request.headers.get('oai-authenticated-user-id');const email=request.headers.get('oai-authenticated-user-email');return !!id&&((!!env.ADMIN_USER_ID&&id===env.ADMIN_USER_ID)||(!!env.ADMIN_EMAIL&&email?.toLowerCase()===env.ADMIN_EMAIL.toLowerCase()))}
async function api(request,env){const {pathname}=new URL(request.url);if(!pathname.startsWith('/api/'))return null;const mutation=['POST','PUT','DELETE','PATCH'].includes(request.method);if(mutation&&request.headers.get('origin')!==new URL(request.url).origin)return json({error:'forbidden'},403);
if(pathname.startsWith('/api/admin')){if(!allowedAdmin(request,env))return json({error:'forbidden'},403);if(!env.BUCKET)return json({error:'unavailable'},503);if(pathname==='/api/admin'&&request.method==='GET')return json(await adminData(env.BUCKET));
if(pathname==='/api/admin/credentials'&&request.method==='POST'){let input;try{input=await body(request)}catch{return json({error:'invalid'},422)}const out={};for(const k of ['uciId','uciProfile','licenseStatus','licenseYear','discipline','federation','rankingHistory','pointsHistory','internationalEntries','resultUrls','documents','lastVerified'])out[k]=text(input[k]);out.verification=text(input.verification);if(!STATES.has(out.verification)||out.uciId&&!/^\d{11}$/.test(out.uciId)||!safeURL(out.uciProfile)||out.licenseYear&&!/^\d{4}$/.test(out.licenseYear)||out.lastVerified&&!/^\d{4}-\d{2}-\d{2}$/.test(out.lastVerified))return json({error:'invalid'},422);out.updatedAt=Date.now();await env.BUCKET.put('private/credentials.json',JSON.stringify(out),{httpMetadata:{contentType:'application/json'}});return json({saved:true})}
if(pathname==='/api/admin/records'&&request.method==='POST'){let input;try{input=await body(request)}catch{return json({error:'invalid'},422)}const out={id:crypto.randomUUID(),createdAt:Date.now()};for(const k of ['kind','title','date','discipline','location','category','position','starters','distance','source','verification','notes'])out[k]=text(input[k],k==='notes'?5000:2000);if(!['race','national-team','performance'].includes(out.kind)||!out.title||out.title.length>180||!['XCO','XCM'].includes(out.discipline)||!STATES.has(out.verification)||!safeURL(out.source)||out.date&&!/^\d{4}-\d{2}-\d{2}$/.test(out.date)||[out.position,out.starters,out.distance].some(v=>v&&(!Number.isFinite(+v)||+v<0)))return json({error:'invalid'},422);out.published=false;await env.BUCKET.put('records/'+out.id+'.json',JSON.stringify(out));return json({saved:true,id:out.id},201)}
const match=pathname.match(/^\/api\/admin\/(enquiries|records)\/([a-f\d-]{36})$/);if(match&&request.method==='DELETE'){await env.BUCKET.delete(match[1]+'/'+match[2]+'.json');return json({deleted:true})}return json({error:'not_found'},404)}
if(pathname==='/api/enquiries'&&request.method==='POST'){if(!env.BUCKET)return json({error:'unavailable'},503);let input;try{input=await body(request)}catch{return json({error:'invalid'},422)}if(text(input.website))return json({error:'invalid'},422);const q={id:crypto.randomUUID(),name:text(input.name,101),email:text(input.email,181),topic:text(input.topic,30),message:text(input.message,3001),experience:text(input.experience,50),region:text(input.region,100),locale:input.locale==='ar'?'ar':'en',consentAt:new Date().toISOString(),createdAt:Date.now()};if(q.name.length<2||q.name.length>100||!/^\S+@[^\s@]+\.[^\s@]+$/.test(q.email)||q.email.length>180||!TOPICS.has(q.topic)||q.message.length<20||q.message.length>3000||input.consent!=='on')return json({error:'invalid'},422);
const ip=request.headers.get('cf-connecting-ip')||'unknown',digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ip));const hash=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');const hour=Math.floor(Date.now()/3600000);const prefix=`rate/${hour}/${hash}/`;const rate=await env.BUCKET.list({prefix,limit:6});if(rate.objects.length>=5)return json({error:'rate_limited'},429);await env.BUCKET.put(prefix+q.id,'1');await env.BUCKET.put('enquiries/'+q.id+'.json',JSON.stringify(q),{httpMetadata:{contentType:'application/json'}});return json({saved:true,id:q.id},201)}return json({error:'not_found'},404)}
async function cleanup(env){if(!env.BUCKET)return;const now=Date.now();for(const key of await list(env.BUCKET,'enquiries/')){if(now-new Date(key.uploaded).getTime()>90*86400000)await env.BUCKET.delete(key.key)}for(const key of await list(env.BUCKET,'rate/'))if(now-new Date(key.uploaded).getTime()>86400000)await env.BUCKET.delete(key.key)}

