const MIME_HEADERS={'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Strict-Transport-Security':'max-age=31536000; includeSubDomains','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self' https://chatgpt.com https://*.chatgpt.com"};
export default {async fetch(request,env,ctx){try{const result=await api(request,env);if(result){const h=new Headers(result.headers);for(const [k,v]of Object.entries(MIME_HEADERS))h.set(k,v);return new Response(result.body,{status:result.status,headers:h})}if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const p=decodeURIComponent(new URL(request.url).pathname).replace(/\/$/,'')||'/';const key=p==='/ar'?'/ar/':p;const asset=ASSETS[key]||ASSETS[p.startsWith('/ar/')?'/ar/404':'/404'];const bytes=Uint8Array.from(atob(asset.base64),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{status:ASSETS[key]?200:404,headers:{...MIME_HEADERS,'Content-Type':asset.type,'Cache-Control':key.startsWith('/assets/')?'public, max-age=3600':'no-cache'}})}catch{return new Response('Request unavailable',{status:500,headers:MIME_HEADERS})}},async scheduled(event,env,ctx){ctx.waitUntil(cleanup(env))}};
